#!/usr/bin/env python3
"""fe_env_tables.h: ENV_LIN, the attack's linear step a block, as Felucca's tools/gen_tables.py makes it (hugelton/Felucca, tools/gen_tables.py: times 1 ms .. 10 s
exponential, 'ENV_LIN = max(1, int((1 << 24) * CTL / (ms * FS / 1000)))'), here for FS 44100 and CTL 32 (eng_formant.c reads it for its TALK morph).
usage: python3 third_party/felucca-host/gen_env_tables.py > third_party/felucca-host/fe_env_tables.h"""
FS, CTL = 44100, 32
ms = [1.0 * (10000 ** (v / 127)) for v in range(128)]
print("/* generated by gen_env_tables.py (44.1 kHz, CTL 32): ENV_LIN[v], the linear attack's step a block for a time of 1 ms x 10000^(v/127) */")
print("static const uint32_t ENV_LIN[128] = {" + ",".join(str(max(1, int((1 << 24) * CTL / (m * FS / 1000)))) for m in ms) + "};")
